def create_api_redirect_url(base_url_api, api_endpoint, opts=None):
    if not all(c.isalnum() or c in '-._' for c in base_url_api):
        raise ValueError("Invalid base URL")
    if not all(c.isalnum() or c in '-._' for c in api_endpoint):
        raise ValueError("Invalid API endpoint")

    parsed_url = urllib.parse.urlparse(base_url_api)
    netloc = parsed_url.netloc
    path = urllib.parse.quote(api_endpoint, safe='')

    if opts:
        query = urllib.parse.urlencode(opts, doseq=True)
        url = f"{parsed_url.scheme}://{netloc}{path}?{query}"
    else:
        url = f"{parsed_url.scheme}://{netloc}{path}"

    parsed_url = urllib.parse.urlparse(url)
    netloc = parsed_url.netloc
    path = parsed_url.path

    if not any(netloc.endswith(domain) for domain in APPROVED_API_DOMAINS):
        raise ValueError("URL does not belong to an allowed domain")

    if path not in ALLOWED_ENDPOINTS:
        raise ValueError("URL endpoint is not allowed")

    return url

