def generate_redirect_link(base_url, endpoint_path, query_info=None):
    if endpoint_path not in ALLOWED_ENDPOINTS:
        raise ValueError("Endpoint is not allowed")

    parsed_url = urllib.parse.urlparse(base_url)
    if parsed_url.netloc not in APPROVED_API_DOMAINS:
        raise ValueError("Domain is not approved")

    full_url = urllib.parse.urljoin(base_url, endpoint_path)
    if query_info:
        query_string = urllib.parse.urlencode(query_info)
        full_url += "?" + query_string

    return full_url

