def handle_project_membership(req_user_id, proj_id, mod, mod_user_id):
    if req_user_id not in USERS:
        return False

    user_role = USERS[req_user_id]["role"]
    if user_role == "admin":
        pass  # Admin can modify any project
    else:
        if proj_id not in PROJECTS:
            return False
        if PROJECTS[proj_id]["owner_id"] != req_user_id:
            return False  # Only project owners can modify their own projects

    if mod_user_id not in USERS:
        return False  # User does not exist

    if mod == "add":
        if mod_user_id in PROJECTS[proj_id]["members"]:
            return False  # User is already a member
        PROJECTS[proj_id]["members"].append(mod_user_id)
    elif mod == "remove":
        if mod_user_id not in PROJECTS[proj_id]["members"]:
            return False  # User is not a member
        PROJECTS[proj_id]["members"].remove(mod_user_id)
    else:
        return False  # Invalid operation

    return True

