def format_string(string: str):
    try:
        # Check if the string contains a placeholder for userinfo
        if "{userinfo." in string:
            # Extract the attribute from the placeholder
            attribute = string.split("{userinfo.")[1].split("}")[0]

            # Check if the attribute is a valid attribute of UserInfo
            if hasattr(UserInfo, attribute):
                # Get the value of the attribute from UserInfo
                value = getattr(UserInfo(), attribute)

                # Format the string with the attribute value
                formatted_string = string.format(userinfo={attribute: value})
                return formatted_string
            else:
                raise ValueError("Invalid attribute in the input string")
        else:
            return string
    except Exception as e:
        raise ValueError("Error formatting the string")

    return string

